import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/PolicySearch.html","title":"PolicySearch","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.48,"words":145},"filePathRelative":"PolicySearch.md"}`),a={name:`PolicySearch.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="policysearch" tabindex="-1"><a class="header-anchor" href="#policysearch"><span>PolicySearch</span></a></h1><p><a href="./強化学習.html">強化学習</a>のPolicy Search。SC234のLec 5からの内容。</p><p><a href="https://www.youtube.com/watch?v=L6OVEmV3NcE&amp;list=PLoROMvodv4rN4wG6Nk6sNpTEbuOSosZdX&amp;index=5" target="_blank" rel="noopener noreferrer">Stanford CS234 Reinforcement Learning I Policy Search 1 I 2024 I Lecture 5 - YouTube</a></p><h2 id="これまでの内容との比較" tabindex="-1"><a class="header-anchor" href="#これまでの内容との比較"><span>これまでの内容との比較</span></a></h2><p>これまでの強化学習のアルゴリズムは以下を全て含む</p><ul><li>Optimization</li><li>Delayed Consequences</li><li>Exploration</li><li>Generalization</li></ul><p>だがそもそもそんな複雑な枠組みでなくやれないか？ 例えばPolicyを単にOnline Optimizationとして得られないか？というのがモチベーション。</p><p>前回までで、<a href="./Value関数.html">Value関数</a>やState-Action Value関数を関数近似することを学んだ（<a href="./Value関数の関数近似.html">Value関数の関数近似</a>）。 そしてポリシーはこれらのValue関数からε-greedyなどで得られた。</p><p>今回はポリシーを直接パラメトライズして、Value関数が最大になるパラメータを求めることでポリシーを得る、という方法を考える。</p><h3 id="今回のポリシーはstochastic" tabindex="-1"><a class="header-anchor" href="#今回のポリシーはstochastic"><span>今回のポリシーはstochastic</span></a></h3><p>前回まではε-greedyなどはdeterministic policyだったが、今回考えるポリシーは基本的にはstochasticなもの。</p><h2 id="例-aliased-gridworld" tabindex="-1"><a class="header-anchor" href="#例-aliased-gridworld"><span>例: Aliased Gridworld</span></a></h2><p>二つの区別出来ない状態があると、deterministic policyでは上手く行かないので、これまでのValue-Basedなやり方は上手く行かない。</p><p>Policy-Basedなやり方なら、最適なポリシーを学習しうる。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};